namespace LastRail.Tests.EditMode {
 public sealed class BNodeSessionControllerTests {
  [Test] public void OriginalNodeBindingNeedsControllerLifetime(){Assert.NotNull(typeof(BDirectAttackInput).Assembly.GetType("LastRail.Run.BNodeSessionController"));}
  [TestCase(false)][TestCase(true)] public void ExternalNativeMutationIsFencedBeforeAnyFurtherControllerCommand(bool pause){using(var c=Controller()){BDirectAttackBasicLoop retained=null;c.AttachLocalTravel(Boarding(),Config(),(n,v)=>retained=Create(n,v),c.Revision);retained.Advance("outside-controller",10000000,500);var before=c.Capture();Assert.Throws<InvalidOperationException>(()=>{if(pause)c.SetPaused("next",true,c.Revision);else c.Advance("next",10000000,500,c.Revision);});Assert.IsTrue(JToken.DeepEquals(before,c.Capture()),"Fence must reject before committing another native command");}}
  static JObject Source()=>BInterceptSourceTests.Read(BInterceptSourceTests.Sample()).OriginalSource.OriginalSource.Capture();
  static JObject Trust(JObject p)=>new JObject(new[]{"origin","nativeContextId","seedHash","sourceHash","nodeId","visitDepth","priorSourceHash"}.Select(k=>new JProperty(k,p[k].DeepClone())));
  static BNodeSessionController Controller(JObject p=null){p=p??Source();var c=new BNodeSessionController((string)p["origin"]["accountId"],(string)p["origin"]["runId"]);c.BindVerifiedNode(p,Trust(p),0);return c;}
  static BTravelRuntimeConfiguration Config(){var p=global::CombatRailJourneyTests.Config();p["offers"]=new JArray();p["throttleMaximumBps"]=13000;p["throttleCruiseBps"]=10000;return BTravelRuntimeConfiguration.LocalValidation(p,BDirectAttackInput.Digest(p));}
  static BDirectAttackBasicLoop Create(BBoardingEventsNodeSnapshot node,BTravelRuntimeConfiguration config){var f=BNamedOperatorSourceTests.Native();return BDirectAttackBasicLoop.CreateOrdinaryTravelRuntime(f.binding,node,BOrdinaryGeometryTests.Geometry(f.binding),10000,config.Capture(),config.Hash);}
  static BBoardingEventsNodeSnapshot Boarding()=>BInterceptSourceTests.Read(BInterceptSourceTests.Sample()).OriginalSource;
  static void Attach(BNodeSessionController c)=>c.AttachLocalTravel(Boarding(),Config(),Create,c.Revision);
  [Test] public void VerifiedNodeCanBindBeforeMotionAndRequiresExplicitTypedSpeed(){using(var c=Controller()){Assert.AreEqual(Source()["nodeId"],c.Capture()["node"]["nodeId"]);Assert.AreEqual(JTokenType.Null,c.Capture()["runtime"].Type);Assert.Throws<InvalidOperationException>(()=>c.AttachLocalTravel(Boarding(),null,Create,c.Revision));Assert.Throws<InvalidOperationException>(()=>Config().RequireOperating());Assert.Throws<InvalidOperationException>(()=>c.RequireAcceptedArrivalOrCompletion());Assert.IsFalse(c.CanStart);}}
  [Test] public void NodePriorLineageReplacementAndRejectedBindingAreAtomic(){var p=BScoutGunnerSourceTests.Sample(0);using(var c=Controller(p)){var next=BScoutGunnerSourceTests.Sample(1);c.BindVerifiedNode(next,Trust(next),1);Assert.AreEqual(5,c.Node.VisitDepth);Assert.AreEqual(2,c.Revision);var before=c.Capture();Assert.Throws<ArgumentException>(()=>c.BindVerifiedNode(p,Trust(p),2));Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));Assert.Throws<InvalidOperationException>(()=>c.BindVerifiedNode(next,Trust(next),1));c.BindVerifiedNode(next,Trust(next),2);Assert.AreEqual(2,c.Revision);var forged=(JObject)next.DeepClone();forged["nodeId"]="foreign";Assert.Throws<ArgumentException>(()=>c.BindVerifiedNode(forged,Trust(next),2));Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));}}
  [Test] public void NativeTravelPauseResumeUsesOriginalOwnersAndOneInputOneNotification(){using(var c=Controller()){int calls=0;c.Bind(_=>calls++);Attach(c);c.Advance("moving",10000000,500,c.Revision);Assert.AreEqual(10000,(long)c.Capture()["runtime"]["travel"]["motion"]["distanceMm"]);c.SetPaused("hold",true,c.Revision);var p=c.Capture();c.Advance("held",100000000,500,c.Revision);Assert.AreEqual(10000,(long)c.Capture()["runtime"]["travel"]["motion"]["distanceMm"]);c.SetPaused("resume",false,c.Revision);c.Advance("again",10000000,500,c.Revision);Assert.AreEqual(20000,(long)c.Capture()["runtime"]["travel"]["motion"]["distanceMm"]);int once=calls;c.Advance("moving",10000000,500,c.Revision);Assert.AreEqual(once,calls);c.Unbind();c.SetPaused("unbind-hold",true,c.Revision);Assert.AreEqual(once,calls);Assert.IsFalse((bool)c.Capture()["observation"]["canPrepareTrustedMaintenance"]);File.WriteAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BNodeController-20261005/actual-node-native.json",c.Capture().ToString());}}
  [Test] public void FailedRuntimeFactoryAndRejectedCommandsPreservePublishedNodeAndState(){using(var c=Controller()){var before=c.Capture();Assert.Throws<InvalidOperationException>(()=>c.AttachLocalTravel(Boarding(),Config(),(n,v)=>throw new InvalidOperationException("factory failed"),c.Revision));Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));Attach(c);before=c.Capture();Assert.Throws<ArgumentException>(()=>c.Advance("invalid",long.MaxValue,1,c.Revision));Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));Assert.Throws<InvalidOperationException>(()=>c.SetPaused("wrong-rev",true,c.Revision-1));Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));}}
  [Test] public void IndependentControllerCacheRestoresExactOriginalNativeAndRejectsTampering(){using(var c=Controller()){Attach(c);c.Advance("before-cache",10000000,500,c.Revision);c.SetPaused("cache-hold",true,c.Revision);var p=c.Capture();BDirectAttackBasicLoop RestoreNative(JObject state){var f=BNamedOperatorSourceTests.Native();var config=Config();return BDirectAttackBasicLoop.RestoreOrdinaryTravelRuntime(state,BDirectAttackInput.Digest(state),f.binding,Boarding(),BOrdinaryGeometryTests.Geometry(f.binding),10000,config.Capture(),config.Hash);}using(var r=BNodeSessionController.Restore(p,BDirectAttackInput.Digest(p),Trust(Source()),RestoreNative,(string)p["accountId"],(string)p["runId"])){Assert.IsTrue(JToken.DeepEquals(p,r.Capture()));r.SetPaused("cache-resume",false,r.Revision);c.SetPaused("cache-resume",false,c.Revision);r.Advance("cache-progress",10000000,500,r.Revision);c.Advance("cache-progress",10000000,500,c.Revision);Assert.IsTrue(JToken.DeepEquals(r.Capture(),c.Capture()));}var forged=(JObject)p.DeepClone();forged["runtime"]["travel"]["motion"]["distanceMm"]=1;Assert.Throws<ArgumentException>(()=>BNodeSessionController.Restore(forged,BDirectAttackInput.Digest(forged),Trust(Source()),RestoreNative,(string)p["accountId"],(string)p["runId"]));Assert.Throws<ArgumentException>(()=>BNodeSessionController.Restore(p,"wrong",Trust(Source()),RestoreNative,(string)p["accountId"],(string)p["runId"]));}}
  [Test] public async Task AsyncNodeCaptureSupersessionUnbindDisposeAndTrustCloning(){var p=BScoutGunnerSourceTests.Sample(0);using(var c=Controller(p)){var next=BScoutGunnerSourceTests.Sample(1);var trust=Trust(next);var pending=new TaskCompletionSource<JObject>();var late=c.BindVerifiedNodeAsync(()=>pending.Task,trust,c.Revision);trust["sourceHash"]="mutated-after-request";c.Unbind();pending.SetResult(next);Assert.IsFalse(await late);Assert.AreEqual(1,c.Node.VisitDepth);Assert.IsTrue(await c.BindVerifiedNodeAsync(()=>Task.FromResult(next),Trust(next),c.Revision));pending=new TaskCompletionSource<JObject>();late=c.BindVerifiedNodeAsync(()=>pending.Task,Trust(BScoutGunnerSourceTests.Sample(2)),c.Revision);c.Dispose();pending.SetResult(BScoutGunnerSourceTests.Sample(2));Assert.IsFalse(await late);Assert.Throws<ObjectDisposedException>(()=>c.Capture());}}
  [Test] public void LiveNodeReplacementStagesNewSourceAndRuntimeBeforeReleasingOldOwner(){
   using(var c=Controller()){
    Attach(c);c.Advance("old-progress",10000000,500,c.Revision);var before=c.Capture();
    var next=BScoutGunnerSourceTests.Sample(1);
    Assert.Throws<InvalidOperationException>(()=>c.BindVerifiedNode(next,Trust(next),c.Revision));
    Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));
    var board=JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-boarding-events-traces-20261004.json"))["syntheticSourceSamples"][1] as JObject;
    var source=BBoardingEventsNodeSnapshot.Read(board,(string)board["sourceHash"],Trust(next));
    Assert.Throws<InvalidOperationException>(()=>c.ReplaceVerifiedLocalSession(next,Trust(next),source,Config(),(n,v)=>throw new InvalidOperationException("new runtime failed"),c.Revision));
    Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));
    c.ReplaceVerifiedLocalSession(next,Trust(next),source,Config(),(n,v)=>{var b=BGunnerInterceptRuntimeTests.Kyle(n);return BDirectAttackBasicLoop.CreateOrdinaryTravelRuntime(b,n,BOrdinaryGeometryTests.Geometry(b),10000,v.Capture(),v.Hash);},c.Revision);
    Assert.AreEqual(5,c.Node.VisitDepth);Assert.AreEqual(0,(long)c.Capture()["runtime"]["travel"]["motion"]["distanceMm"]);
    Assert.AreEqual(next["sourceHash"],c.Capture()["runtime"]["travel"]["nodeSourceHash"]);
    c.Advance("new-progress",10000000,500,c.Revision);Assert.AreEqual(10000,(long)c.Capture()["runtime"]["travel"]["motion"]["distanceMm"]);
    Assert.Throws<InvalidOperationException>(()=>Attach(c));
   }
  }
  static BOperationDestinationReceipt Destination(BOperationDestinationIntent i)=>BOperationDestinationReceipt.Read(new JObject{["version"]="operation.map-destination.v1",["requestId"]=i.CommandId,["revision"]=i.ExpectedRevision+1,["phase"]="TRAVELLING",["pendingEdgeId"]=i.EdgeId}.ToString(),i);
  [Test] public async Task DestinationAcceptedResponseCannotBecomeArrivalOrReplaceNativeNode(){using(var c=Controller()){var i=new BOperationDestinationIntent((string)Source()["origin"]["accountId"],c.Node.RunId,"choose",4,"original-edge");Assert.IsTrue(await c.ConfirmDestinationAsync(i,()=>Task.FromResult(Destination(i)),c.Revision));Assert.AreEqual(Source()["nodeId"],c.Capture()["node"]["nodeId"]);Assert.IsFalse(Destination(i).CanProveArrival);var p=c.Capture();var pending=new TaskCompletionSource<BOperationDestinationReceipt>();var late=c.ConfirmDestinationAsync(i,()=>pending.Task,c.Revision);c.Unbind();pending.SetResult(Destination(i));Assert.IsFalse(await late);Assert.IsTrue(JToken.DeepEquals(p,c.Capture()));}}
  [Test] public async Task ExistingBearerDestinationWirePreservesOriginalBodyKeyAndRevisionErrors(){var wire=new RunRiskBindingTests.Wire();var i=new BOperationDestinationIntent("a","run original","choose",4,"original-edge");wire.Reply=r=>Task.FromResult(RunApiHttpResponse.Success(200,Destination(i).Capture()["response"].ToString()));var client=new BOperationDestinationClient(new GameApiAuthenticatedHttpTransport(wire));var token=new GameApiAccessToken("lst1.fixture");await client.ConfirmAsync(i,token);Assert.AreEqual("POST",wire.Last.Method);Assert.AreEqual("/v1/runs/run%20original/operation-map/destination",wire.Last.EndpointPath);Assert.IsTrue(JToken.DeepEquals(i.Body(),JObject.Parse(wire.Last.BodyJson)));Assert.AreEqual(2,i.Body().Count);Assert.IsTrue(wire.Last.Headers.Any(h=>h.Name=="Idempotency-Key"&&h.Value=="choose"));Assert.IsTrue(wire.Last.Headers.Any(h=>h.Name=="Authorization"));wire.Reply=r=>Task.FromResult(RunApiHttpResponse.Success(409,"{\"errorCode\":\"operation_map_revision_conflict\"}"));Assert.ThrowsAsync<InvalidOperationException>(async()=>await client.ConfirmAsync(i,token));Assert.AreEqual(4,i.ExpectedRevision);}
  [TestCase("revision")][TestCase("pendingEdgeId")][TestCase("phase")][TestCase("requestId")]
  public void MalformedDestinationResponseCannotAuthorizeLocalTransition(string field){var i=new BOperationDestinationIntent("a","r","choose",4,"edge");var p=(JObject)Destination(i).Capture()["response"];p[field]=field=="revision"?new JValue(6):new JValue("wrong");Assert.Throws<ArgumentException>(()=>BOperationDestinationReceipt.Read(p.ToString(),i));}
 }
}
